// Package modelcatalog is the extracted model catalogue of the JS
// runtime: PROVIDER_MODELS (open-sse/config/providerModels.js, built from
// providers/registry + config/ttsModels.js) plus the pricing tables of
// open-sse/providers/pricing.js (PROVIDER_PRICING / MODEL_PRICING /
// PATTERN_PRICING / FREE_MODEL_NAMESPACES).
//
// The data lives in catalog.json, generated by
// tools/extract_provider_models.mjs — never hand-edit it; re-run the
// script. Lookups port the getter semantics of
// open-sse/config/providerModels.js (findModel incl. the kiro/kr
// dash→dot tolerance, OpenCode family fallbacks, Codex "-review") and
// open-sse/providers/pricing.js getPricingForModel (provider override →
// free namespace → canonical → glob pattern).
package modelcatalog

import (
	_ "embed"
	"encoding/json"
	"regexp"
	"strings"
	"sync"

	"9router-go/internal/providers"
)

//go:embed catalog.json
var catalogJSON []byte

type patternEntry struct {
	Pattern string             `json:"pattern"`
	Pricing map[string]float64 `json:"pricing"`
}

type catalogFile struct {
	Counts         map[string]int              `json:"counts"`
	ProviderModels map[string][]map[string]any `json:"providerModels"`
	Pricing        struct {
		ProviderPricing     map[string]map[string]map[string]float64 `json:"providerPricing"`
		ModelPricing        map[string]map[string]float64            `json:"modelPricing"`
		PatternPricing      []patternEntry                           `json:"patternPricing"`
		FreeModelNamespaces []string                                 `json:"freeModelNamespaces"`
		ZeroPricing         map[string]float64                       `json:"zeroPricing"`
	} `json:"pricing"`
	Failures []map[string]any `json:"failures"`
}

var (
	loadOnce sync.Once
	data     *catalogFile
	loadErr  error
	// aliasKey maps provider id -> the PROVIDER_MODELS key for that
	// provider (registry `alias || id`), and keySet holds every key.
	aliasKey map[string]string
)

func load() (*catalogFile, error) {
	loadOnce.Do(func() {
		var cf catalogFile
		if err := json.Unmarshal(catalogJSON, &cf); err != nil {
			loadErr = err
			return
		}
		data = &cf
		aliasKey = map[string]string{}
		for _, p := range providers.All() {
			key := p.Alias
			if key == "" {
				key = p.ID
			}
			if _, ok := cf.ProviderModels[key]; ok {
				aliasKey[p.ID] = key
			}
		}
	})
	return data, loadErr
}

// LoadError reports a catalog parse failure (nil in practice — the JSON
// is generated by the extractor and embedded).
func LoadError() error { _, err := load(); return err }

// Failures returns the extraction failures recorded in catalog.json.
func Failures() []map[string]any {
	cf, err := load()
	if err != nil {
		return nil
	}
	return cf.Failures
}

// Counts returns the extractor's counts block (providerKeys, models,
// modelsWithTargetFormat, pricedModels, providerPricedModels, patterns).
func Counts() map[string]int {
	cf, err := load()
	if err != nil {
		return nil
	}
	return cf.Counts
}

// resolveKey maps a caller-supplied provider id-or-alias to the
// PROVIDER_MODELS key (alias || id), mirroring how the JS getters are
// called with aliasOrId.
func resolveKey(provider string) string {
	cf, err := load()
	if err != nil {
		return provider
	}
	if _, ok := cf.ProviderModels[provider]; ok {
		return provider
	}
	if p, ok := providers.Get(provider); ok {
		if _, ok := cf.ProviderModels[p.Alias]; ok && p.Alias != "" {
			return p.Alias
		}
		if _, ok := cf.ProviderModels[p.ID]; ok {
			return p.ID
		}
	}
	if k, ok := aliasKey[provider]; ok {
		return k
	}
	return provider
}

// Models returns the raw catalogue entries for a provider (nil when the
// provider has no curated models — passthrough/fetcher providers).
func Models(provider string) []map[string]any {
	cf, err := load()
	if err != nil {
		return nil
	}
	return cf.ProviderModels[resolveKey(provider)]
}

var suffixRe = regexp.MustCompile(`\([^()]+\)\s*$`)

// stripSuffix splits a trailing "(level)" thinking suffix off a model id
// (providerModels.js findModel / getModelUpstreamId).
func stripSuffix(model string) (base, suffix string) {
	loc := suffixRe.FindStringIndex(model)
	if loc == nil {
		return model, ""
	}
	return strings.TrimSpace(model[:loc[0]]), model[loc[0]:]
}

var digitDashRe = regexp.MustCompile(`(\d)-(\d)`)

// normalizeModelID ports models/schema.js normalizeModelId (digit-dash →
// digit-dot), used only for the DOT_VERSION_PROVIDERS (kr, kiro).
func normalizeModelID(model string) string {
	return digitDashRe.ReplaceAllString(model, "$1.$2")
}

// findEntry ports providerModels.js findModel over the catalogue list of
// one resolved key.
func findEntry(key, model string) map[string]any {
	cf, err := load()
	if err != nil {
		return nil
	}
	models := cf.ProviderModels[key]
	if models == nil {
		return nil
	}
	base, _ := stripSuffix(model)
	for _, m := range models {
		id, _ := m["id"].(string)
		if id == model || id == base {
			return m
		}
	}
	if key == "kr" || key == "kiro" {
		if normalized := normalizeModelID(base); normalized != base {
			for _, m := range models {
				if id, _ := m["id"].(string); id == normalized {
					return m
				}
			}
		}
	}
	return nil
}

func strSlice(v any) []string {
	list, ok := v.([]any)
	if !ok {
		return nil
	}
	out := make([]string, 0, len(list))
	for _, item := range list {
		if s, ok := item.(string); ok {
			out = append(out, s)
		}
	}
	return out
}

// --- OpenCode family fallbacks (providers/models/helpers.js) ---

var openCodeAliases = map[string]bool{
	"oc": true, "opencode": true, "ocg": true,
	"opencode-go": true, "ocz": true, "opencode-zen": true,
}

func isOpenCodeAlias(keyOrID string) bool { return openCodeAliases[keyOrID] }

var museSparkRe = regexp.MustCompile(`(?i)^muse[-_]?spark($|[-_:. ])`)

// isMuseSparkModel ports helpers.js isMuseSparkModel.
func isMuseSparkModel(model string) bool {
	clean, _ := stripSuffix(model)
	base := clean
	if i := strings.LastIndex(clean, "/"); i >= 0 {
		base = clean[i+1:]
	}
	return museSparkRe.MatchString(base)
}

type familyFormats struct {
	supported []string
	target    string
}

var openCodeFamilies = []struct {
	re        *regexp.Regexp
	supported []string
	target    string
}{
	{regexp.MustCompile(`(?i)^(grok|gpt|muse[-_]?spark)`), []string{"openai-responses"}, "openai-responses"},
	{regexp.MustCompile(`^deepseek-v4-(pro|flash)`), []string{"openai", "claude", "openai-responses"}, ""},
	{regexp.MustCompile(`^(minimax|qwen)`), []string{"openai", "claude"}, ""},
	{regexp.MustCompile(`(?i)^claude-`), []string{"claude"}, ""},
}

// opencodeFamilyFormats ports helpers.js opencodeFamilyFormats (the
// unknown-id fallback; the model id is matched without its "(level)"
// suffix, exactly as in JS).
func opencodeFamilyFormats(model string) *familyFormats {
	base, _ := stripSuffix(model)
	for _, f := range openCodeFamilies {
		if f.re.MatchString(base) {
			return &familyFormats{supported: f.supported, target: f.target}
		}
	}
	return nil
}

// --- ModelMeta ---

// Meta is one model's catalogue metadata. Raw preserves the full
// registry entry (thinking hints, params, voices, …) for consumers that
// need fields beyond the chatCore subset.
type Meta struct {
	Found            bool
	TargetFormat     string   // getModelTargetFormat ("" = provider default)
	SupportedFormats []string // getModelSupportedFormats (nil = undeclared)
	UpstreamID       string   // upstreamModelId override ("" = the model itself)
	Type             string   // getModelType: raw kind||type ("" = llm default)
	QuotaFamily      string   // getModelQuotaFamily ("" = "normal")
	Strip            []string // getModelStrip
	Raw              map[string]any
}

// ModelMeta resolves the catalogue metadata for (provider, model),
// porting getModelTargetFormat / getModelSupportedFormats /
// getModelType / getModelUpstreamId / getModelQuotaFamily of
// open-sse/config/providerModels.js.
func ModelMeta(provider, model string) Meta {
	key := resolveKey(provider)
	entry := findEntry(key, model)
	openCode := isOpenCodeAlias(provider) || isOpenCodeAlias(key)

	var meta Meta
	if entry != nil {
		meta.Found = true
		meta.Raw = entry
		if s, ok := entry["targetFormat"].(string); ok {
			meta.TargetFormat = s
		}
		if sf := strSlice(entry["supportedFormats"]); sf != nil {
			meta.SupportedFormats = sf
		}
		if s, ok := entry["kind"].(string); ok && s != "" {
			meta.Type = s
		} else if s, ok := entry["type"].(string); ok {
			meta.Type = s
		}
		if s, ok := entry["quotaFamily"].(string); ok {
			meta.QuotaFamily = s
		}
		meta.Strip = strSlice(entry["strip"])
		meta.UpstreamID = upstreamOverride(key, model, entry)
	}

	// getModelTargetFormat: the OpenCode+MuseSpark rule runs BEFORE the
	// registry lookup in JS, so it wins over any entry value.
	if openCode && isMuseSparkModel(model) {
		meta.TargetFormat = "openai-responses"
	} else if entry == nil && openCode {
		// Unknown OpenCode id: family fallback (getModelTargetFormat /
		// getModelSupportedFormats — supported defaults to ["openai"]).
		if fam := opencodeFamilyFormats(model); fam != nil {
			if meta.TargetFormat == "" {
				meta.TargetFormat = fam.target
			}
			if meta.SupportedFormats == nil {
				meta.SupportedFormats = fam.supported
			}
		}
		if meta.SupportedFormats == nil {
			meta.SupportedFormats = []string{"openai"}
		}
	}
	return meta
}

// Lookup is ModelMeta with an explicit found flag (entry-based hits
// only; OpenCode family fallbacks report Found=false like the JS
// getters returning values for unregistered ids).
func Lookup(provider, model string) (Meta, bool) {
	m := ModelMeta(provider, model)
	return m, m.Found
}

// upstreamOverride ports getModelUpstreamId, reduced to the override:
// it returns "" when the resolved upstream id equals the requested
// model id (chatcore's "" = the model itself convention).
func upstreamOverride(key, model string, entry map[string]any) string {
	base, suffix := stripSuffix(model)
	resolved := ""
	if entry != nil {
		if s, ok := entry["upstreamModelId"].(string); ok && s != "" {
			resolved = s
		} else if s, ok := entry["id"].(string); ok {
			resolved = s
		}
	}
	if resolved != "" {
		resBase, resSuffix := stripSuffix(resolved)
		useSuffix := suffix
		if useSuffix == "" {
			useSuffix = resSuffix
		}
		if out := resBase + useSuffix; out != model {
			return out
		}
		return ""
	}
	// Codex "-review" special case (getModelUpstreamId): only for cx.
	if key == "cx" && strings.HasSuffix(base, "-review") {
		return strings.TrimSuffix(base, "-review") + suffix
	}
	return ""
}

// UpstreamID ports getModelUpstreamId verbatim (always returns the
// resolved id, including the requested id itself when nothing maps).
func UpstreamID(provider, model string) string {
	key := resolveKey(provider)
	entry := findEntry(key, model)
	if ov := upstreamOverride(key, model, entry); ov != "" {
		return ov
	}
	return model
}

// --- Pricing (open-sse/providers/pricing.js) ---

func priceRecord(m map[string]float64) map[string]any {
	if m == nil {
		return nil
	}
	out := make(map[string]any, len(m))
	for k, v := range m {
		out[k] = v
	}
	return out
}

// IsFreeModel ports pricing.js isFreeModel (FREE_MODEL_NAMESPACES).
func IsFreeModel(model string) bool {
	cf, err := load()
	if err != nil || model == "" {
		return false
	}
	lower := strings.ToLower(model)
	for _, ns := range cf.Pricing.FreeModelNamespaces {
		if strings.HasPrefix(lower, ns) {
			return true
		}
	}
	return false
}

var globCache sync.Map // pattern string -> *regexp.Regexp

// matchPattern ports pricing.js matchPattern ("*" glob, case-insensitive).
func matchPattern(pattern, model string) bool {
	if re, ok := globCache.Load(pattern); ok {
		return re.(*regexp.Regexp).MatchString(model)
	}
	parts := strings.Split(pattern, "*")
	for i, p := range parts {
		parts[i] = regexp.QuoteMeta(p)
	}
	re, err := regexp.Compile("(?i)^" + strings.Join(parts, ".*") + "$")
	if err != nil {
		return false
	}
	globCache.Store(pattern, re)
	return re.MatchString(model)
}

// PricingFor ports getPricingForModel: provider override → free
// namespace ($0) → canonical MODEL_PRICING → PATTERN_PRICING.
// Returns nil when nothing prices the model.
func PricingFor(provider, model string) map[string]any {
	cf, err := load()
	if err != nil || model == "" {
		return nil
	}
	if provider != "" {
		if models, ok := cf.Pricing.ProviderPricing[provider]; ok {
			if rec, ok := models[model]; ok {
				return priceRecord(rec)
			}
		}
	}
	if IsFreeModel(model) {
		return priceRecord(cf.Pricing.ZeroPricing)
	}
	base := model
	if i := strings.LastIndex(model, "/"); i >= 0 {
		base = model[i+1:]
	}
	if rec, ok := cf.Pricing.ModelPricing[base]; ok {
		return priceRecord(rec)
	}
	if rec, ok := cf.Pricing.ModelPricing[model]; ok {
		return priceRecord(rec)
	}
	for _, pat := range cf.Pricing.PatternPricing {
		if matchPattern(pat.Pattern, base) || matchPattern(pat.Pattern, model) {
			return priceRecord(pat.Pricing)
		}
	}
	return nil
}

// DefaultProviderPricing returns PROVIDER_PRICING in the shape
// internal/db expects for its DefaultProviderPricing hook
// (provider -> model -> pricing record, values as float64).
func DefaultProviderPricing() map[string]any {
	cf, err := load()
	if err != nil {
		return nil
	}
	out := make(map[string]any, len(cf.Pricing.ProviderPricing))
	for provider, models := range cf.Pricing.ProviderPricing {
		pm := make(map[string]any, len(models))
		for model, rec := range models {
			pm[model] = priceRecord(rec)
		}
		out[provider] = pm
	}
	return out
}
